<script setup>
import { computed, ref, watch } from 'vue'; import { MoreHorizontal, Plus, Search } from 'lucide-vue-next'; import { useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; import { useInvoiceStore } from '@/stores/invoice'; import { formatCurrency, formatDate } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import BaseSelect from '@/components/ui/BaseSelect.vue'; import ConfirmDialog from '@/components/ui/ConfirmDialog.vue'; import Pagination from '@/components/ui/Pagination.vue'; import { useUiStore } from '@/stores/ui';
const router=useRouter(),auth=useAuthStore(),store=useInvoiceStore(),ui=useUiStore();const search=ref(''),doc=ref('semua'),pay=ref('semua'),page=ref(1),menu=ref(null),cancel=ref(null),pageSize=5;const readOnly=computed(()=>auth.role==='manager');const rows=computed(()=>store.invoices.filter(x=>(doc.value==='semua'||x.status===doc.value)&&(pay.value==='semua'||x.paymentStatus===pay.value)&&`${x.number} ${x.name} ${x.client}`.toLowerCase().includes(search.value.toLowerCase())).slice((page.value-1)*pageSize,page.value*pageSize));const total=computed(()=>store.invoices.filter(x=>(doc.value==='semua'||x.status===doc.value)&&(pay.value==='semua'||x.paymentStatus===pay.value)&&`${x.number} ${x.name} ${x.client}`.toLowerCase().includes(search.value.toLowerCase())).length);watch([search,doc,pay],()=>page.value=1);const docBadge=s=>({draft:['Draft','default'],published:['Diterbitkan','info'],cancelled:['Dibatalkan','danger']}[s]);const payBadge=s=>({belum_dibayar:['Belum Dibayar','neutral'],dibayar_sebagian:['Dibayar Sebagian','warning'],lunas:['Lunas','success'],jatuh_tempo:['Jatuh Tempo','danger']}[s]);const totalDue=x=>x.items.reduce((a,i)=>a+i.price*i.qty,0)-x.discount;const go=(name,id)=>router.push({name,params:id?{id}:undefined});const doCancel=()=>{store.cancelInvoice(cancel.value.id);ui.notify('Invoice berhasil dibatalkan.');cancel.value=null;menu.value=null};
</script>
<template><div class="p-6"><header class="mb-5 flex items-start justify-between"><div><h1 class="text-xl font-semibold text-[#172033]">Invoice</h1><p class="mt-0.5 text-sm text-[#667085]">Kelola invoice dan tagihan untuk klien perusahaan.</p></div><BaseButton v-if="!readOnly" @click="go('invoice-create')"><Plus :size="15" />Buat Invoice</BaseButton></header><div class="mb-4 flex items-center gap-3"><BaseInput v-model="search" class="max-w-xs flex-1" placeholder="Cari nomor, nama, klien..."><template #prefix><Search :size="14" /></template></BaseInput><BaseSelect v-model="doc" class="w-36" :options="[{value:'semua',label:'Semua Dokumen'},{value:'draft',label:'Draft'},{value:'published',label:'Diterbitkan'},{value:'cancelled',label:'Dibatalkan'}]"/><BaseSelect v-model="pay" class="w-40" :options="[{value:'semua',label:'Semua Pembayaran'},{value:'belum_dibayar',label:'Belum Dibayar'},{value:'dibayar_sebagian',label:'Dibayar Sebagian'},{value:'lunas',label:'Lunas'},{value:'jatuh_tempo',label:'Jatuh Tempo'}]"/></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><table class="w-full min-w-[1000px]"><thead><tr class="border-b border-[#E2E6EC] bg-[#F9FAFB]"><th v-for="h in ['Nomor Invoice','Nama Invoice','Klien','Tanggal','Jatuh Tempo','Total','Dokumen','Pembayaran','Aksi']" :key="h" class="px-4 py-3 text-left text-xs font-medium text-[#667085] first:px-5">{{h}}</th></tr></thead><tbody><tr v-for="(invoice,index) in rows" :key="invoice.id" class="border-b border-[#F3F4F6] hover:bg-gray-50"><td class="px-5 py-3.5 text-sm font-semibold text-[#173B6C]">{{invoice.number}}</td><td class="px-4 py-3.5 text-sm text-[#172033]">{{invoice.name}}</td><td class="px-4 py-3.5 text-sm text-[#667085]">{{invoice.client}}</td><td class="px-4 py-3.5 text-sm text-[#667085]">{{formatDate(invoice.date)}}</td><td class="px-4 py-3.5 text-sm text-[#667085]">{{formatDate(invoice.dueDate)}}</td><td class="px-4 py-3.5 text-right text-sm font-medium text-[#172033]">{{formatCurrency(totalDue(invoice))}}</td><td class="px-4 py-3.5"><BaseBadge :variant="docBadge(invoice.status)[1]">{{docBadge(invoice.status)[0]}}</BaseBadge></td><td class="px-4 py-3.5"><BaseBadge :variant="payBadge(invoice.paymentStatus)[1]">{{payBadge(invoice.paymentStatus)[0]}}</BaseBadge></td><td class="relative px-4 py-3.5"><button class="rounded p-1.5 text-[#667085] hover:bg-gray-100" @click="menu=menu===invoice.id?null:invoice.id"><MoreHorizontal :size="15"/></button><div v-if="menu===invoice.id" :class="['absolute right-4 z-20 w-44 rounded-lg border border-[#E2E6EC] bg-white py-1 shadow-lg',index>=rows.length-3?'bottom-10':'top-10']"><button class="w-full px-4 py-2 text-left text-sm hover:bg-gray-50" @click="go('invoice-detail',invoice.id)">Detail</button><button class="w-full px-4 py-2 text-left text-sm hover:bg-gray-50" @click="go('invoice-preview',invoice.id)">Preview PDF</button><button v-if="!readOnly&&invoice.status!=='cancelled'" class="w-full px-4 py-2 text-left text-sm hover:bg-gray-50" @click="go('invoice-edit',invoice.id)">Edit</button><button v-if="!readOnly&&invoice.status!=='cancelled'" class="w-full px-4 py-2 text-left text-sm hover:bg-gray-50" @click="cancel=invoice">Batalkan</button></div></td></tr></tbody></table><Pagination :page="page" :total="total" :per-page="pageSize" @change="page=$event"/></section><ConfirmDialog :open="Boolean(cancel)" title="Batalkan Invoice" message="Invoice akan tetap tersimpan sebagai riwayat." confirm-label="Batalkan" danger @cancel="cancel=null" @confirm="doCancel"/><button v-if="menu" class="fixed inset-0 z-10" @click="menu=null"/></div></template>
